mapper.select:
SELECT COALESCE(sys01_secondary_auth_yn = 'true', false)
  FROM sys01_company
 WHERE sys01_company_id = #{companyId}

SELECT COUNT(*)
  FROM ( SELECT sys83_temp_password, sys83_reg_date
           FROM sys83_secondary_auth_user
          WHERE sys83_company_id = #{companyId}
            AND sys83_person_id = #{personId}
          ORDER BY sys83_reg_date DESC
          LIMIT 1 ) x
 WHERE x.sys83_temp_password = #{tempPassword}
   AND x.sys83_reg_date >= f_sysdate() - (#{validMinutes} * interval '1 minute')
